from pydantic_settings import BaseSettings


class Settings(BaseSettings):
    aws_mode: bool = False

    # Docker defaults; EKS gets AWS endpoint values from the shared ConfigMap.
    dynamodb_endpoint_url: str = "http://localstack:4566"
    dynamodb_table_name: str = "ibts-transactions"
    sqs_endpoint_url: str = "http://localstack:4566"
    sqs_queue_name: str = "ibts-settlement-events"

    # Used only in local mode. AWS mode relies on the boto3 credential chain / IRSA.
    aws_access_key_id: str = "test"
    aws_secret_access_key: str = "test"
    aws_default_region: str = "ap-south-1"

    idempotency_guard_url: str = "http://idempotency-guard:8080"
    payment_router_url: str = "http://payment-router:8081"
    bank_adapter_url: str = "http://bank-adapter:8082"

    port: int = 8083

    def aws_client_kwargs(self, endpoint_url: str) -> dict:
        kwargs = {"region_name": self.aws_default_region}

        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url

        if not self.aws_mode:
            kwargs["aws_access_key_id"] = self.aws_access_key_id
            kwargs["aws_secret_access_key"] = self.aws_secret_access_key
        elif endpoint_url.startswith("http://localstack"):
            raise ValueError("AWS_MODE=true cannot use a LocalStack endpoint")

        return kwargs

    class Config:
        env_file = ".env"
        case_sensitive = False


settings = Settings()
